css.content:
/* Typewriter: the caret is a thin rule that blinks; it stops for reduced motion. */
.typewriter-caret { display: inline-block; width: 1px; height: 1em; margin-inline-start: 2px; vertical-align: text-bottom; background: currentColor; animation: typewriter-blink 1s steps(1) infinite; }
@keyframes typewriter-blink { 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .typewriter-caret { animation: none; } }

source.content:
'use client';
import {forwardRef, useEffect, useRef, useState, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';
import {usePrefersReducedMotion} from '../number-ticker/use-reduced-motion';

export interface TypewriterProps extends HTMLAttributes<HTMLSpanElement> {
  /** The string to type. Screen readers get all of it at once. */
  text: string;
  /** Milliseconds per character. Default 40. */
  speed?: number;
  /** Milliseconds to wait before the first character. Default 0. */
  delay?: number;
  /** Show a blinking caret. Default true. */
  cursor?: boolean;
  /** Called once the last character is shown (also straight away for reduced motion). */
  onComplete?: () => void;
}

/**
 * Types `text` one character at a time. With `prefers-reduced-motion` the full string shows at once.
 * The typed characters are `aria-hidden`; an `sr-only` copy holds the whole text.
 */
export const Typewriter = forwardRef<HTMLSpanElement, TypewriterProps>(function Typewriter({text, speed = 40, delay = 0, cursor = true, onComplete, className, ...rest}, ref) {
  const chars = Array.from(text); // by code point, so an emoji is never cut in half
  const [count, setCount] = useState(chars.length);
  const reduced = usePrefersReducedMotion();
  const done = useRef(onComplete);
  done.current = onComplete;

  useEffect(() => {
    const len = Array.from(text).length;
    if (reduced) { setCount(len); done.current?.(); return; }
    let timer: ReturnType<typeof setTimeout>;
    let n = 0;
    const tick = () => {
      n += 1;
      setCount(n);
      if (n < len) timer = setTimeout(tick, speed); else done.current?.();
    };
    setCount(0);
    timer = setTimeout(tick, delay || speed);
    return () => clearTimeout(timer);
  }, [text, speed, delay, reduced]);

  return (
    <span ref={ref} className={cx('typewriter', className)} {...rest}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">{chars.slice(0, count).join('')}{cursor && <span className="typewriter-caret" />}</span>
    </span>
  );
});
